@import "tailwindcss";
@import "@repo/design-system/styles/globals.css";

/* Marketing color scales & design tokens */
@theme inline {
  /* Brand colors */
  --color-hastoggle-pink: #ff0080;
  --color-hastoggle-blue: #0070f3;
  --color-hastoggle-cyan: #50e3c2;
  --color-hastoggle-orange: #f5a623;
  --color-hastoggle-violet: #7928ca;
  --color-hastoggle-green: #008000;

  /* ht-blue (hue: 236) */
  --color-ht-blue-50: oklch(0.99 0.003 236);
  --color-ht-blue-100: oklch(0.98 0.009 236);
  --color-ht-blue-200: oklch(0.965 0.018 236);
  --color-ht-blue-300: oklch(0.953 0.028 235.946);
  --color-ht-blue-400: oklch(0.871 0.08 236);
  --color-ht-blue-500: oklch(0.789 0.135 236);
  --color-ht-blue-600: oklch(0.707 0.192 235.993);
  --color-ht-blue-700: oklch(0.624 0.176 236.001);
  --color-ht-blue-800: oklch(0.542 0.153 236);
  --color-ht-blue-900: oklch(0.46 0.13 236);
  --color-ht-blue-950: oklch(0.419 0.1 236);

  /* ht-red (hue: 20) */
  --color-ht-red-50: oklch(0.99 0.003 20);
  --color-ht-red-100: oklch(0.98 0.009 20);
  --color-ht-red-200: oklch(0.965 0.02 20);
  --color-ht-red-300: oklch(0.953 0.03 20);
  --color-ht-red-400: oklch(0.871 0.089 20);
  --color-ht-red-500: oklch(0.789 0.158 20);
  --color-ht-red-600: oklch(0.707 0.237 20);
  --color-ht-red-700: oklch(0.624 0.283 20);
  --color-ht-red-800: oklch(0.542 0.246 20.005);
  --color-ht-red-900: oklch(0.46 0.208 20);
  --color-ht-red-950: oklch(0.419 0.1 20);

  /* ht-green (hue: 147) */
  --color-ht-green-50: oklch(0.99 0.009 147);
  --color-ht-green-100: oklch(0.98 0.027 147);
  --color-ht-green-200: oklch(0.965 0.058 147);
  --color-ht-green-300: oklch(0.953 0.089 147);
  --color-ht-green-400: oklch(0.871 0.29 147);
  --color-ht-green-500: oklch(0.789 0.329 146.998);
  --color-ht-green-600: oklch(0.707 0.295 147);
  --color-ht-green-700: oklch(0.624 0.26 146.998);
  --color-ht-green-800: oklch(0.542 0.226 146.994);
  --color-ht-green-900: oklch(0.46 0.192 147);
  --color-ht-green-950: oklch(0.419 0.1 147);

  /* ht-greenish (hue: 156) */
  --color-ht-greenish-50: oklch(0.99 0.008 156);
  --color-ht-greenish-100: oklch(0.98 0.025 156);
  --color-ht-greenish-200: oklch(0.965 0.053 156);
  --color-ht-greenish-300: oklch(0.953 0.082 156.001);
  --color-ht-greenish-400: oklch(0.871 0.259 156);
  --color-ht-greenish-500: oklch(0.789 0.265 155.998);
  --color-ht-greenish-600: oklch(0.707 0.237 156);
  --color-ht-greenish-700: oklch(0.624 0.21 156);
  --color-ht-greenish-800: oklch(0.542 0.182 156);
  --color-ht-greenish-900: oklch(0.46 0.154 156);
  --color-ht-greenish-950: oklch(0.419 0.1 156);

  /* ht-darkgreen (hue: 169) */
  --color-ht-darkgreen-50: oklch(0.99 0.008 169);
  --color-ht-darkgreen-100: oklch(0.98 0.023 169);
  --color-ht-darkgreen-200: oklch(0.965 0.049 169);
  --color-ht-darkgreen-300: oklch(0.953 0.076 169.005);
  --color-ht-darkgreen-400: oklch(0.871 0.238 168.997);
  --color-ht-darkgreen-500: oklch(0.789 0.216 168.996);
  --color-ht-darkgreen-600: oklch(0.707 0.193 169);
  --color-ht-darkgreen-700: oklch(0.624 0.171 168.996);
  --color-ht-darkgreen-800: oklch(0.542 0.148 168.999);
  --color-ht-darkgreen-900: oklch(0.46 0.126 168.994);
  --color-ht-darkgreen-950: oklch(0.419 0.1 169);

  /* ht-cyan (hue: 206) */
  --color-ht-cyan-50: oklch(0.99 0.005 206);
  --color-ht-cyan-100: oklch(0.98 0.015 206);
  --color-ht-cyan-200: oklch(0.965 0.033 206);
  --color-ht-cyan-300: oklch(0.953 0.05 205.984);
  --color-ht-cyan-400: oklch(0.871 0.142 205.994);
  --color-ht-cyan-500: oklch(0.789 0.18 206.003);
  --color-ht-cyan-600: oklch(0.707 0.162 206.003);
  --color-ht-cyan-700: oklch(0.624 0.143 206);
  --color-ht-cyan-800: oklch(0.542 0.124 206.008);
  --color-ht-cyan-900: oklch(0.46 0.105 206);
  --color-ht-cyan-950: oklch(0.419 0.096 206.008);

  /* ht-orange (hue: 47) */
  --color-ht-orange-50: oklch(0.99 0.003 47);
  --color-ht-orange-100: oklch(0.98 0.01 47);
  --color-ht-orange-200: oklch(0.965 0.021 47);
  --color-ht-orange-300: oklch(0.953 0.033 47.025);
  --color-ht-orange-400: oklch(0.871 0.096 47.001);
  --color-ht-orange-500: oklch(0.789 0.168 47.005);
  --color-ht-orange-600: oklch(0.707 0.222 47);
  --color-ht-orange-700: oklch(0.624 0.196 46.992);
  --color-ht-orange-800: oklch(0.542 0.17 47);
  --color-ht-orange-900: oklch(0.46 0.144 47);
  --color-ht-orange-950: oklch(0.419 0.1 47);

  /* Extended radius */
  --radius-4xl: 2rem;

  /* Marketing animations */
  --animate-rerender: rerender 1s ease-in-out 1;
  --animate-highlight: highlight 1s ease-in-out 1;
  --animate-shimmer: shimmer 2s infinite;

  /* Switzer font (loaded via CDN in marketing layout) */
  --font-switzer: "Switzer", system-ui, sans-serif;
}

/* Marketing keyframes */
@keyframes rerender {
  0% {
    border-color: var(--color-hastoggle-orange);
  }
  40% {
    border-color: var(--color-hastoggle-orange);
  }
}

@keyframes highlight {
  0% {
    background: var(--color-hastoggle-orange);
    color: white;
  }
  40% {
    background: var(--color-hastoggle-orange);
    color: white;
  }
}

@keyframes highlightFadeIn {
  from {
    background-color: transparent;
  }
  to {
    background-color: #808080;
  }
}

@keyframes shimmer {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

@keyframes move-x {
  0% {
    transform: translateX(var(--move-x-from));
  }
  100% {
    transform: translateX(var(--move-x-to));
  }
}

.highlighted-line {
  padding: 2px 8px 2px 0;
  border-radius: 12px;
  animation: highlightFadeIn 0.2s ease-in-out forwards;
}

/* Shiki code syntax highlighting styles */
.shiki {
  color: var(--shiki-light);
  background-color: var(--shiki-light-bg);
  @apply border-border;
}

.shiki span {
  color: var(--shiki-light);
}

.dark .shiki {
  color: var(--shiki-dark);
  background-color: var(--shiki-dark-bg);
}

.dark .shiki span {
  color: var(--shiki-dark);
}

.shiki code {
  display: grid;
  font-size: 13px;
  counter-reset: line;
}

.shiki .line:before {
  content: counter(line);
  counter-increment: line;

  @apply inline-block w-4 mr-8 text-muted-foreground text-right;
}

.shiki[title]:before {
  content: attr(title);
  @apply inline-block text-muted-foreground text-right mb-6 text-sm;
}

