1	"use client";
2	
3	import { AnimatePresence, motion } from "motion/react";
4	import { useState } from "react";
5	import { Container } from "./container";
6	
7	interface SignUpSuccess {
8	  message: string;
9	}
10	
11	interface SignUpError {
12	  error: {
13	    message: string;
14	    name: string;
15	  };
16	}
17	
18	type SignUpResponse = SignUpSuccess | SignUpError;
19	
20	const buttonCopy = {
21	  idle: "Add me",
22	  loading: <Spinner />,
23	  success: "Check your inbox!",
24	};
25	
26	export function Digest() {
27	  const [loading, setLoading] = useState<"idle" | "loading" | "success">(
28	    "idle"
29	  );
30	  const [error, setError] = useState<SignUpError | null>(null);
31	
32	  const handleSignUp = async (event: React.SyntheticEvent<HTMLFormElement>) => {
33	    event.preventDefault();
34	    const form = event.target as HTMLFormElement;
35	    const emailInput = form.elements.namedItem("email") as HTMLInputElement;
36	    setLoading("loading");
37	    try {
38	      const res = await fetch("/api/confirm", {
39	        method: "POST",
40	        headers: {
41	          "Content-Type": "application/json",
42	        },
43	        body: JSON.stringify({
44	          email: emailInput.value,
45	        }),
46	      });
47	      const data: SignUpResponse = await res.json();
48	      if ("error" in data) {
49	        setError(data);
50	        setLoading("idle");
51	      } else {
52	        setLoading("success");
53	        form.reset();
54	      }
55	    } catch (_error) {
56	      setError({
57	        error: {
58	          message: "A network error occurred. Please try again.",
59	          name: "NetworkError",
60	        },
61	      });
62	      setLoading("idle");
63	    }
64	  };
65	
66	  return (
67	    <section aria-label="Digest sign-up" id="digest">
68	      <Container className="relative py-20" size="xs">
69	        <form className="lg:pl-16" onSubmit={handleSignUp}>
