1	"use client";
2	
3	import { Button } from "@repo/design-system/components/ui/button";
4	import { motion } from "motion/react";
5	import Image from "next/image";
6	import {
7	  type Dispatch,
8	  Suspense,
9	  useCallback,
10	  useReducer,
11	  useState,
12	} from "react";
13	import { Boundary } from "@/components/ui/boundary";
14	import { initHighlighter } from "@/lib/highlighter";
15	import { CodeDisplay } from "./code";
16	import { getCodeSnippets } from "./code-snippets";
17	import {
18	  initialMobileState,
19	  type MobileAction,
20	  type MobileState,
21	  mobileCounterReducer,
22	} from "./counter-state";
23	import { SkeletonCode } from "./skeleton";
24	
25	const flipVariants = {
26	  initial: { rotateY: 90, opacity: 0 },
27	  animate: { rotateY: 0, opacity: 1 },
28	  exit: { rotateY: -90, opacity: 0 },
29	};
30	
31	export function CounterMobile() {
32	  const [state, dispatch] = useReducer(
33	    mobileCounterReducer,
34	    initialMobileState
35	  );
36	  const [componentToShow, setComponentToShow] = useState<
37	    "codeDisplay" | "buttonDisplay"
38	  >("buttonDisplay");
39	
40	  const pendingHighlighter = initHighlighter();
41	
42	  const handleAnimationComplete = useCallback(() => {
43	    setComponentToShow("buttonDisplay");
44	  }, []);
45	
46	  const handleButtonClick = () => {
47	    setComponentToShow("codeDisplay");
48	  };
49	
50	  const codeSnippets = getCodeSnippets(state.count);
51	
52	  return (
53	    <div className="mx-auto h-full max-w-2xl rounded-lg bg-zinc-50 px-4 py-6 shadow-2xl ring-1 ring-black/10 sm:px-6">
54	      <Boundary
55	        animateRerendering={false}
56	        color="default"
57	        labels={[state.label]}
58	        size="medium"
59	      >
60	        {componentToShow === "codeDisplay" && (
61	          <motion.div
62	            animate="animate"
63	            className="w-full"
64	            exit="exit"
65	            initial="initial"
66	            key="codeDisplay"
67	            transition={{ duration: 0.5 }}
68	            variants={flipVariants}
69	          >
70	            <Suspense fallback={<SkeletonCode />}>
71	              <CodeDisplay
72	                code={codeSnippets}
73	                onAnimationComplete={handleAnimationComplete}
74	                pendingHighlighter={pendingHighlighter}
75	              />
76	            </Suspense>
77	          </motion.div>
78	        )}
79	
80	        {componentToShow === "buttonDisplay" && (
81	          <motion.div
82	            animate="animate"
83	            exit="exit"
84	            initial="initial"
85	            key="buttonDisplay"
86	            transition={{ duration: 0.3 }}
87	            variants={flipVariants}
88	          >
89	            <CounterContent
90	              dispatch={dispatch}
91	              onButtonClick={handleButtonClick}
92	              state={state}
93	            />
94	          </motion.div>
95	        )}
96	      </Boundary>
97	    </div>
98	  );
99	}
100	
101	interface CounterContentProps {
102	  dispatch: Dispatch<MobileAction>;
103	  onButtonClick: () => void;
104	  state: MobileState;
105	}
106	
107	function CounterContent({
108	  state,
109	  dispatch,
110	  onButtonClick,
111	}: CounterContentProps) {
112	  return (
113	    <div className="flex w-full flex-col gap-y-6">
114	      <div className="flex justify-between self-center sm:self-auto">
115	        <div className="hidden max-w-64 space-y-2 text-balance sm:block">
116	          <h3 className="mt-5 font-semibold text-gray-900 text-xl">
117	            {state.title}
118	          </h3>
119	          <p className="text-gray-700 text-sm">{state.paragraph}</p>
120	          <p className="text-gray-700 text-sm">{state.cta}</p>
121	        </div>
122	
123	        <div className="relative aspect-square w-56 overflow-hidden rounded-2xl ring-1 ring-black/10">
124	          <Image
125	            alt="squirrel"
126	            className="absolute inset-x-0 top-0 aspect-square w-full object-cover"
127	            height={240}
128	            priority
