"use client";

import { use, useEffect, useState } from "react";
import type { createHighlighter } from "shiki";
import { SkeletonCode } from "./skeleton";

type Highlighter = Awaited<ReturnType<typeof createHighlighter>>;

const LINE_ANIMATION_INTERVAL_MS = 300;

interface CodeDisplayProps {
  code: Array<{ id: number; code: string }>;
  onAnimationComplete: () => void;
  pendingHighlighter: Promise<Highlighter>;
}

export function CodeDisplay({
  code,
  pendingHighlighter,
  onAnimationComplete,
}: CodeDisplayProps) {
  const highlighter = use(pendingHighlighter);
  const [highlightedCode, setHighlightedCode] = useState<string>("");
  const [currentLine, setCurrentLine] = useState<number>(0);
  const codeline = code[currentLine];

  useEffect(() => {
    const highlighted = highlighter.codeToHtml(codeline.code, {
      lang: "jsx",
      theme: "ayu-dark",
    });

    const lines = highlighted.split("\n");
    const highlightedLines = lines
      .map((line: string, index: number) => {
        if (index !== 0 && index === currentLine) {
          return `<span class="highlighted-line">${line}</span>`;
        }
        return line;
      })
      .join("\n");

    setHighlightedCode(highlightedLines);
  }, [highlighter, codeline, currentLine]);

  useEffect(() => {
    let interval: NodeJS.Timeout | undefined;
    const totalLines = codeline.code.split("\n").length - 1;
    if (currentLine < totalLines) {
      interval = setInterval(() => {
        setCurrentLine((prevLine) => prevLine + 1);
      }, LINE_ANIMATION_INTERVAL_MS);
    } else {
      onAnimationComplete();
    }
    return () => clearInterval(interval);
  }, [codeline, currentLine, onAnimationComplete]);

  if (!highlightedCode) {
    return <SkeletonCode />;
  }

  return (
    <div className="my-auto h-60 rounded-md bg-gray-950 p-5 sm:h-72 lg:h-80">
      <div
        className="overflow-scroll whitespace-pre-wrap text-sm sm:overflow-hidden sm:text-base"
        // biome-ignore lint/security/noDangerouslySetInnerHtml: Shiki outputs HTML for syntax highlighting — input is controlled, not user-supplied
        dangerouslySetInnerHTML={{ __html: highlightedCode }}
      />
    </div>
  );
}

import { cn } from "@repo/design-system/lib/utils";

export const SkeletonCode = ({ isLoading }: { isLoading?: boolean }) => (
  <div
    className={cn(
      "my-auto h-60 rounded-2xl bg-gray-900/80 p-4 sm:h-[18rem] lg:h-[20rem]",
      {
        "relative overflow-hidden before:absolute before:inset-0 before:-translate-x-full before:animate-[shimmer_1.5s_infinite] before:bg-gradient-to-r before:from-transparent before:via-white/10 before:to-transparent":
          isLoading,
      }
    )}
  >
    <div className="space-y-2.5">
      <div className="h-4 w-6/12 rounded-lg bg-gray-700 lg:h-6" />
      <div className="h-4 w-9/12 rounded-lg bg-gray-700 lg:h-6" />
      <div className="h-4 w-3/12 rounded-lg bg-gray-700 lg:h-6" />
      <div className="h-4 w-3/12 rounded-lg bg-gray-700 lg:h-6" />
      <div className="h-4 w-9/12 rounded-lg bg-gray-700 lg:h-6" />
      <div className="h-4 w-12/12 rounded-lg bg-gray-700 lg:h-6" />
      <div className="h-4 w-2/12 rounded-lg bg-gray-700 lg:h-6" />
      <div className="h-4 w-4/12 rounded-lg bg-gray-700 lg:h-6" />
      <div className="h-4 w-3/12 rounded-lg bg-gray-700 lg:h-6" />
    </div>
  </div>
);

